--!nocheck
--!nolint
repeat task.wait() until shared["_db/processors"] and shared["_db/connect"]

local Compute = {}
local Proxy = {}

setmetatable(Proxy, {
	__newindex = function(_, key, value)
		if key == "ProcessReceipt" and typeof(value) == "function" then
			shared["_db/connect"]:AddProcessor(tostring(value), "Neutral", value)
		else
			rawset(Compute, key, value)
		end
	end,
	__index = Compute
})

export type ProcessReceipt = {
	ProcessReceipt: any
}

return Proxy :: ProcessReceipt

shared["_db/info"] = {
	datastorename = "Donation Board v4",
	reconnecttimer = 2.5,
	minimumgrouprank = 254,
	version = 4.0,
}

shared["_db/keys"] = {
	settingsdata = "donationboard@settings",
	donationsdata = "donationboard@donations",
	transferreddata = "donationboard@transferreddata",
}

shared["_db/environment"] = {
	context = game:GetService("RunService"):IsClient() and "Client" or "Server",
	state = game:GetService("RunService"):IsRunning() and "Running" or "Stopped",
	runmode = game:GetService("RunService"):IsRunMode(),
	studiomode = game:GetService("RunService"):IsStudio(),
	debugmode = true,
	safeguard = false,
}

shared["_db/receipts"] = {}
shared["_db/processors"] = {}
shared["_db/memory"] = {}
shared["_db/autosavetimer"] = 10

if (not shared["_db/environment"]) then
	game:GetService("MessagingService"):PublishAsync("_db/shared", {
		["_db/info"] = shared["_db/info"],
		["_db/keys"] = shared["_db/keys"],
	})
end

--!nocheck
--!nolint
local Signal = {}
Signal.__index = Signal


function Signal.new()
	local self = setmetatable({}, Signal)

	self._bevent = Instance.new("BindableEvent")
	self.Event = self._bevent.Event

	return self
end


function Signal:Fire(...)
	self._bevent:Fire(...)
end

function Signal:Connect(...)
	return self._bevent.Event:Connect(...)
end

function Signal:ConnectParallel(...)
	return self._bevent.Event:ConnectParallel(...)
end


function Signal:Once(...)
	return self._bevent.Event:Once(...)
end


function Signal:Wait()
	return self._bevent.Event:Wait()
end

return Signal

