								self.Content.Frame.UIGradient.Color = ColorSequence.new({
									ColorSequenceKeypoint.new(0, self.Color1),
									ColorSequenceKeypoint.new(0.5, self.Color2),
									ColorSequenceKeypoint.new(1, self.Color3),
