								local frameMax = (absPos.X + absSize.X) / parentSize.X

								local t = (relativeX - frameMin) / (frameMax - frameMin)

								return ((1 - math.clamp(t, 0, 1)) * (self.Max - self.Min)) + self.Min
							end
						end


